```python
import hashlib
import os
import bcrypt
import jwt
from datetime import datetime, timedelta, timezone

def hash_password(password: str) -> str:
    """Hash a password using bcrypt with a generated salt."""
    if not isinstance(password, str):
        raise TypeError("Password must be a string")
    password_bytes = password.encode('utf-8')
    salt = bcrypt.gensalt(rounds=12)  # Strong but still fast enough
    hashed = bcrypt.hashpw(password_bytes, salt)
    return hashed.decode('utf-8')

def verify_password(password: str, stored_hash: str) -> bool:
    """Verify a password against a bcrypt hash."""
    if not isinstance(password, str) or not isinstance(stored_hash, str):
        raise TypeError("Both password and stored hash must be strings")
    try:
        password_bytes = password.encode('utf-8')
        stored_hash_bytes = stored_hash.encode('utf-8')
        return bcrypt.checkpw(password_bytes, stored_hash_bytes)
    except (ValueError, TypeError):
        # If the stored hash is malformed, verification fails
        return False

def create_token(user_id: str, secret: str) -> str:
    """Create a JWT access token that expires in 15 minutes."""
    if not isinstance(user_id, str) or not isinstance(secret, str):
        raise TypeError("user_id and secret must be strings")
    payload = {
        'user_id': user_id,
        'exp': datetime.now(timezone.utc) + timedelta(minutes=15),
        'iat': datetime.now(timezone.utc),
        'type': 'access'
    }
    token = jwt.encode(payload, secret, algorithm='HS256')
    return token

def verify_token(token: str, secret: str) -> str | None:
    """
    Verify and decode a JWT access token.
    Returns the user_id if valid, or None if invalid or expired.
    """
    if not isinstance(token, str) or not isinstance(secret, str):
        return None
    try:
        payload = jwt.decode(token, secret, algorithms=['HS256'])
        # Ensure it's an access token, not a different token type
        if payload.get('type') != 'access':
            return None
        return payload.get('user_id')
    except jwt.ExpiredSignatureError:
        # Token has expired
        return None
    except jwt.InvalidTokenError:
        # Token is malformed, signature invalid, or other issues
        return None
