import bcrypt
import jwt
from datetime import datetime, timedelta, timezone

# Token settings
JWT_ALGORITHM = "HS256"
TOKEN_EXPIRE_MINUTES = 15


def hash_password(password: str) -> str:
    """Hash a plaintext password with bcrypt and return the hash as a string."""
    pw_bytes = password.encode("utf-8")
    salt = bcrypt.gensalt()
    hash_bytes = bcrypt.hashpw(pw_bytes, salt)
    return hash_bytes.decode("utf-8")


def verify_password(password: str, stored_hash: str) -> bool:
    """Verify a plaintext password against a stored bcrypt hash."""
    pw_bytes = password.encode("utf-8")
    hash_bytes = stored_hash.encode("utf-8")
    return bcrypt.checkpw(pw_bytes, hash_bytes)


def create_token(user_id: str, secret: str) -> str:
    """Create a JWT access token valid for 15 minutes."""
    now = datetime.now(timezone.utc)
    payload = {
        "sub": user_id,
        "iat": now,
        "exp": now + timedelta(minutes=TOKEN_EXPIRE_MINUTES),
    }
    return jwt.encode(payload, secret, algorithm=JWT_ALGORITHM)


def verify_token(token: str, secret: str) -> str | None:
    """Verify a JWT access token. Returns the user_id if valid, otherwise None."""
    try:
        payload = jwt.decode(token, secret, algorithms=[JWT_ALGORITHM])
        return payload.get("sub")
    except jwt.PyJWTError:
        return None
    except Exception:
        # Defensive fallback to avoid leaking any unexpected errors
        return None
