                cryptoKey,
                encodedPlaintext
            );

            // 4. Concatenate IV + Ciphertext (Tag is appended to ciphertext by Web Crypto)
            const result = new Uint8Array(iv.length + ciphertextBuffer.byteLength);
            result.set(iv);
            result.set(new Uint8Array(ciphertextBuffer), iv.length);

            return result;
