                    {
                        name: "AES-GCM",
                        iv: iv,
                        additionalData: new TextEncoder().encode(aad)
                    },
                    cryptoKey,
                    ciphertext
                );
                return new TextDecoder().decode(decrypted);
            } catch (e) {
                throw new Error("Decryption failed: Data integrity compromised or invalid key.");
            }
