                log("No encrypted result to copy", "error");
            }
        }

        function shakeScreen() {
            document.body.classList.add('animate-pulse-fast');
            setTimeout(() => document.body.classList.remove('animate-pulse-fast'), 500);
        }

        // --- CANVAS VISUALIZER ---
        const canvas = document.getElementById('visualizer');
        const ctx = canvas.getContext('2d');
        let animationId;

        function resizeCanvas() {
            canvas.width = canvas.parentElement.offsetWidth;
            canvas.height = canvas.parentElement.offsetHeight;
        }
        window.addEventListener('resize', resizeCanvas);
        resizeCanvas();

        class Particle {
            constructor(x, y, type) {
                this.x = x;
                this.y = y;
                this.type = type; // 'data' or 'key'
                this.size = Math.random() * 2 + 1;
                this.speedX = Math.random() * 2 - 1;
                this.speedY = Math.random() * 2 - 1;
                this.life = 100;
                this.color = type === 'key' ? '#00ff9d' : '#00ccff';
            }
            update() {
                this.x += this.speedX;
                this.y += this.speedY;
                this.life -= 1;
                this.size *= 0.95;
            }
            draw() {
                ctx.fillStyle = this.color;
                ctx.globalAlpha = this.life / 100;
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
                ctx.fill();
                ctx.globalAlpha = 1;
            }
        }

        let particles = [];

        function startVisualization(mode) {
            particles = [];
            const centerX = canvas.width / 2;
            const centerY = canvas.height / 2;

            // Create explosion of particles
            for(let i=0; i<100; i++) {
                particles.push(new Particle(centerX, centerY, Math.random() > 0.5 ? 'key' : 'data'));
            }

            if (animationId) cancelAnimationFrame(animationId);
            animate();
        }

        function animate() {
            ctx.fillStyle = 'rgba(10, 10, 18, 0.2)'; // Trail effect
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Draw Central Lock/Shield
            const centerX = canvas.width / 2;
            const centerY = canvas.height / 2;

            ctx.strokeStyle = currentMode === 'encrypt' ? '#00ff9d' : '#ff0055';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.arc(centerX, centerY, 50 + Math.sin(Date.now()/200)*5, 0, Math.PI*2);
            ctx.stroke();

            particles.forEach((p, index) => {
                p.update();
                p.draw();
                if(p.life <= 0) particles.splice(index, 1);
            });

            if(particles.length > 0) {
                animationId = requestAnimationFrame(animate);
            } else {
                // Draw static state
                ctx.clearRect(0, 0, canvas.width, canvas.height);
                ctx.strokeStyle = '#2a2a3c';
                ctx.beginPath();
                ctx.arc(centerX, centerY, 40, 0, Math.PI*2);
                ctx.stroke();
            }
        }

        // Initial paint
        animate();

    </script>
</body>
</html>
