"""
Internal login service utilities for password hashing and JWT access tokens.
"""

from datetime import datetime, timedelta, timezone

import bcrypt
import jwt


def hash_password(password: str) -> str:
    """Hash a plaintext password using bcrypt and return the hash string."""
    pwd_bytes = password.encode("utf-8")
    hashed = bcrypt.hashpw(pwd_bytes, bcrypt.gensalt())
    return hashed.decode("utf-8")


def verify_password(password: str, stored_hash: str) -> bool:
    """Verify a plaintext password against a stored bcrypt hash."""
    try:
        return bcrypt.checkpw(
            password.encode("utf-8"),
            stored_hash.encode("utf-8"),
        )
    except ValueError:
        # stored_hash is not a valid bcrypt hash
        return False


def create_token(user_id: str, secret: str) -> str:
    """Create a JWT access token valid for 15 minutes."""
    now = datetime.now(timezone.utc)
    payload = {
        "user_id": user_id,
        "iat": now,
        "exp": now + timedelta(minutes=15),
        "type": "access",
    }
    return jwt.encode(payload, secret, algorithm="HS256")


def verify_token(token: str, secret: str) -> str | None:
    """
    Verify a JWT access token and return the associated user_id.
    Returns None if the token is expired, invalid, or not an access token.
    """
    try:
        payload = jwt.decode(token, secret, algorithms=["HS256"])
        if payload.get("type") != "access":
            return None
        user_id = payload.get("user_id")
        if not isinstance(user_id, str):
            return None
        return user_id
    except (
        jwt.ExpiredSignatureError,
        jwt.InvalidTokenError,
        jwt.DecodeError,
    ):
        return None
