import bcrypt
import jwt
from datetime import datetime, timedelta
from typing import Optional

def hash_password(password: str) -> str:
    """Hash a plaintext password using bcrypt."""
    # The password must be encoded to bytes, and bcrypt returns a bytes hash.
    # We convert it to a string for convenience.
    hashed_bytes = bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt())
    return hashed_bytes.decode('utf-8')

def verify_password(password: str, stored_hash: str) -> bool:
    """Verify a plaintext password against a stored bcrypt hash."""
    try:
        # Encode both to bytes for bcrypt.checkpw
        return bcrypt.checkpw(
            password.encode('utf-8'),
            stored_hash.encode('utf-8')
        )
    except (ValueError, TypeError):
        # Invalid hash format or other errors
        return False

def create_token(user_id: str, secret: str) -> str:
    """Create a JWT access token that expires after 15 minutes.

    The token payload includes:
    - 'sub': the user_id (subject)
    - 'exp': expiration time (UTC)
    """
    payload = {
        'sub': user_id,
        'exp': datetime.utcnow() + timedelta(minutes=15)
    }
    # HS256 is a good default symmetric algorithm
    token = jwt.encode(payload, secret, algorithm='HS256')
    return token

def verify_token(token: str, secret: str) -> Optional[str]:
    """Verify and decode a JWT token.

    Returns the user_id (subject) if the token is valid and not expired,
    otherwise returns None.
    """
    try:
        payload = jwt.decode(token, secret, algorithms=['HS256'])
        return payload.get('sub')
    except jwt.ExpiredSignatureError:
        # Token is past its expiration time
        return None
    except jwt.InvalidTokenError:
        # Token is malformed, signature invalid, or other issues
        return None
