import bcrypt
import jwt
import uuid
from datetime import datetime, timedelta, timezone


def hash_password(password: str) -> str:
    """Hash a password using bcrypt. Returns the hash as an ASCII string."""
    if not isinstance(password, str):
        raise TypeError("Password must be a string")
    pwd_bytes = password.encode("utf-8")
    # Use a cost factor appropriate for your threat model and hardware (≥12 recommended).
    hashed = bcrypt.hashpw(pwd_bytes, bcrypt.gensalt(rounds=12))
    return hashed.decode("utf-8")


def verify_password(password: str, stored_hash: str) -> bool:
    """Verify a plaintext password against a stored bcrypt hash."""
    if not isinstance(password, str) or not isinstance(stored_hash, str):
        return False
    try:
        return bcrypt.checkpw(password.encode("utf-8"), stored_hash.encode("utf-8"))
    except Exception:
        # Fail-secure: never leak validation errors to the caller.
        return False


def create_token(user_id: str, secret: str) -> str:
    """Create an HMAC-signed JWT access token that expires after 15 minutes."""
    if not isinstance(user_id, str) or not user_id:
        raise ValueError("user_id must be a non-empty string")
    if not isinstance(secret, str) or len(secret) < 32:
        raise ValueError("secret must be at least 32 bytes")

    now = datetime.now(timezone.utc)
    payload = {
        "sub": user_id,
        "iat": now,
        "exp": now + timedelta(minutes=15),
        "jti": uuid.uuid4().hex,
    }
    return jwt.encode(payload, secret, algorithm="HS256")


def verify_token(token: str, secret: str) -> str | None:
    """
    Verify an access token.

    Returns the user_id if the token is valid and not expired; otherwise None.
    """
    if not isinstance(token, str) or not isinstance(secret, str) or not secret:
        return None
    try:
        payload = jwt.decode(
            token,
            secret,
            algorithms=["HS256"],
            options={"require": ["exp", "iat", "sub", "jti"]},
        )
        user_id = payload.get("sub")
        if not isinstance(user_id, str):
            return None
        return user_id
    except (jwt.ExpiredSignatureError, jwt.InvalidTokenError):
        return None
    except Exception:
        return None
