try:
    import bcrypt
    HAS_BCRYPT = True
except ImportError:
    HAS_BCRYPT = False
    print("Warning: bcrypt not installed. Using PBKDF2 (less secure).")


def hash_password(password: str) -> str:
    """Hash a password with a salt using bcrypt or PBKDF2 (fallback)."""
    if HAS_BCRYPT:
        # bcrypt handles salting automatically
        hashed = bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt())
        return hashed.decode('utf-8')
    else:
        # PBKDF2 fallback with SHA256 and 100,000 iterations
        salt = os.urandom(16)
        dk = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
        # Store as hex: salt_hex:hash_hex
        return salt.hex() + ':' + dk.hex()


def verify_password(password: str, stored_hash: str) -> bool:
    """Verify a password against a stored hash."""
    if HAS_BCRYPT:
        try:
            return bcrypt.checkpw(password.encode('utf-8'), stored_hash.encode('utf-8'))
        except ValueError:
            return False
    else:
        try:
            salt_hex, hash_hex = stored_hash.split(':')
            salt = bytes.fromhex(salt_hex)
            stored_dk = bytes.fromhex(hash_hex)
            new_dk = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
            return new_dk == stored_dk
        except (ValueError, AttributeError):
            return False


def create_token(user_id: str, secret: str) -> str:
    """Create a JWT token valid for 15 minutes."""
    payload = {
        'user_id': user_id,
        'exp': int(time.time()) + 900,  # 15 minutes
        'iat': int(time.time())
    }
