import hashlib
import os
import time
import base64
import json
import hmac
from typing import Optional

# For password hashing we use bcrypt if available, otherwise fallback to hashlib
try:
    import bcrypt
    BCRYPT_AVAILABLE = True
except ImportError:
    BCRYPT_AVAILABLE = False

# For token creation we use PyJWT if available, otherwise pure Python implementation
try:
    import jwt
    JWT_AVAILABLE = True
except ImportError:
    JWT_AVAILABLE = False


def hash_password(password: str) -> str:
    """
    Hash a password using bcrypt (preferred) or SHA-256 with salt.
    Returns a string that includes the algorithm identifier, salt, and hash.
    """
    if BCRYPT_AVAILABLE:
        # bcrypt automatically handles salting
        password_bytes = password.encode('utf-8')
        hashed = bcrypt.hashpw(password_bytes, bcrypt.gensalt())
        return hashed.decode('utf-8')
    else:
        # Fallback: SHA-256 with random 16-byte salt
        salt = os.urandom(16)
        password_bytes = password.encode('utf-8')
        hash_obj = hashlib.pbkdf2_hmac('sha256', password_bytes, salt, 100000)
        # Format: sha256$salt_base64$hash_base64
        return f"sha256${base64.b64encode(salt).decode('ascii')}${base64.b64encode(hash_obj).decode('ascii')}"


def verify_password(password: str, stored_hash: str) -> bool:
    """
    Verify a password against a stored hash.
    Supports bcrypt and the SHA-256 fallback format.
    """
    if BCRYPT_AVAILABLE and stored_hash.startswith('$2b$') or stored_hash.startswith('$2a$') or stored_hash.startswith('$2y$'):
        # bcrypt hash
        return bcrypt.checkpw(password.encode('utf-8'), stored_hash.encode('utf-8'))
    elif stored_hash.startswith('sha256$'):
        # SHA-256 fallback format
        try:
            _, salt_b64, hash_b64 = stored_hash.split('$')
            salt = base64.b64decode(salt_b64)
            stored_hash_bytes = base64.b64decode(hash_b64)

            password_bytes = password.encode('utf-8')
            computed_hash = hashlib.pbkdf2_hmac('sha256', password_bytes, salt, 100000)
            return hmac.compare_digest(computed_hash, stored_hash_bytes)
        except (ValueError, base64.binascii.Error):
            return False
    else:
        # Unknown format
        return False


def create_token(user_id: str, secret: str) -> str:
    """
    Create a JWT token valid for 15 minutes.
    Uses PyJWT if available, otherwise implements a minimal HMAC-based token.
    """
    now = int(time.time())
    expiry = now + 900  # 15 minutes = 900 seconds

    payload = {
        'sub': user_id,
        'iat': now,
        'exp': expiry,
        'type': 'access'
    }

    if JWT_AVAILABLE:
        # Use PyJWT library
        token = jwt.encode(payload, secret, algorithm='HS256')
        # In PyJWT >= 2.0, encode returns a string; in older versions it returns bytes
        if isinstance(token, bytes):
            return token.decode('utf-8')
        return token
    else:
        # Fallback: manual HMAC-SHA256 JWT implementation
        header = {
            'alg': 'HS256',
            'typ': 'JWT'
        }

        header_b64 = base64.urlsafe_b64encode(json.dumps(header).encode()).rstrip(b'=').decode()
        payload_b64 = base64.urlsafe_b64encode(json.dumps(payload).encode()).rstrip(b'=').decode()

        message = f"{header_b64}.{payload_b64}"
        signature = hmac.new(
            secret.encode('utf-8'),
            message.encode('utf-8'),
            hashlib.sha256
        ).digest()
        signature_b64 = base64.urlsafe_b64encode(signature).rstrip(b'=').decode()

        return f"{header_b64}.{payload_b64}.{signature_b64}"


def verify_token(token: str, secret: str) -> Optional[str]:
    """
    Verify a JWT token and return the user_id if valid, None otherwise.
    """
    try:
        if JWT_AVAILABLE:
            # Use PyJWT library
            try:
                payload = jwt.decode(token, secret, algorithms=['HS256'])
                # Check if token is still valid (jwt.decode already checks exp)
                if payload.get('type') != 'access':
                    return None
                return payload.get('sub')
            except jwt.ExpiredSignatureError:
                return None
            except jwt.InvalidTokenError:
                return None
        else:
            # Fallback: manual JWT verification
            parts = token.split('.')
            if len(parts) != 3:
                return None

            header_b64, payload_b64, signature_b64 = parts

            # Recreate the message and verify signature
            message = f"{header_b64}.{payload_b64}"

            # Decode the signature from base64 (with padding restoration)
            padding = 4 - len(signature_b64) % 4
            if padding != 4:
                signature_b64 += '=' * padding

            try:
                expected_sig = hmac.new(
                    secret.encode('utf-8'),
                    message.encode('utf-8'),
                    hashlib.sha256
                ).digest()
                received_sig = base64.urlsafe_b64decode(signature_b64)
            except Exception:
                return None

            if not hmac.compare_digest(expected_sig, received_sig):
                return None

            # Decode payload
            padding = 4 - len(payload_b64) % 4
            if padding != 4:
                payload_b64 += '=' * padding

            try:
                payload_json = base64.urlsafe_b64decode(payload_b64)
                payload = json.loads(payload_json)
            except Exception:
                return None

            # Check expiry
            now = time.time()
            if now > payload.get('exp', 0):
                return None

            # Check token type
            if payload.get('type') != 'access':
                return None

            return payload.get('sub')

    except Exception:
        return None
