_ISSUER = "telecom_5g_core_login"
_TOKEN_LIFETIME_MINUTES = 15


def hash_password(password: str) -> str:
    """Hash a plaintext password using bcrypt."""
    password_bytes = password.encode("utf-8")
    hashed = bcrypt.hashpw(password_bytes, bcrypt.gensalt())
    return hashed.decode("utf-8")


def verify_password(password: str, stored_hash: str) -> bool:
    """Verify a plaintext password against a stored bcrypt hash."""
    try:
        return bcrypt.checkpw(
            password.encode("utf-8"),
            stored_hash.encode("utf-8"),
        )
    except (ValueError, TypeError):
        # Return False if the stored hash is malformed
        return False


def create_token(user_id: str, secret: str) -> str:
    """Create a JWT access token that expires after 15 minutes."""
    now = datetime.now(timezone.utc)
    payload = {
        "sub": user_id,
        "iat": now,
        "exp": now + timedelta(minutes=_TOKEN_LIFETIME_MINUTES),
        "iss": _ISSUER,
    }
    return jwt.encode(payload, secret, algorithm=_ALGORITHM)


