```python
import hashlib
import os
import time
import hmac
import base64
from typing import Optional

try:
    import bcrypt
except ImportError:
    bcrypt = None

try:
    import jwt
except ImportError:
    jwt = None


def hash_password(password: str) -> str:
    """
    Hash a password using bcrypt with a generated salt.
    Falls back to SHA-256 with a random salt if bcrypt is not available.
    """
    if bcrypt:
        salt = bcrypt.gensalt()
        hashed = bcrypt.hashpw(password.encode('utf-8'), salt)
        return hashed.decode('utf-8')
    else:
        # Fallback: SHA-256 with random salt
        salt = os.urandom(16).hex()
        hashed = hashlib.pbkdf2_hmac(
            'sha256',
            password.encode('utf-8'),
            salt.encode('utf-8'),
            100000
        )
        return f"sha256${salt}${hashed.hex()}"


def verify_password(password: str, stored_hash: str) -> bool:
    """
    Verify a password against a stored hash.
    Supports bcrypt hashes and fallback SHA-256 format.
    """
    if bcrypt and stored_hash.startswith('$2b$') or stored_hash.startswith('$2a$'):
        try:
            return bcrypt.checkpw(password.encode('utf-8'), stored_hash.encode('utf-8'))
        except ValueError:
            return False
    elif stored_hash.startswith('sha256$'):
        parts = stored_hash.split('$')
        if len(parts) != 3:
            return False
        _, salt, stored_digest = parts
        computed_hash = hashlib.pbkdf2_hmac(
            'sha256',
            password.encode('utf-8'),
            salt.encode('utf-8'),
            100000
        )
        return hmac.compare_digest(computed_hash.hex(), stored_digest)
    else:
        return False


def create_token(user_id: str, secret: str) -> str:
    """
    Create a JWT token that expires after 15 minutes.
    Falls back to HMAC-based token if PyJWT is not available.
    """
    if jwt:
        payload = {
            'user_id': user_id,
            'exp': int(time.time()) + 900,  # 15 minutes
            'iat': int(time.time())
        }
        return jwt.encode(payload, secret, algorithm='HS256')
    else:
        # Fallback: HMAC-based token
        expiration = int(time.time()) + 900
        payload = f"{user_id}:{expiration}"
        signature = hmac.new(
            secret.encode('utf-8'),
            payload.encode('utf-8'),
            hashlib.sha256
        ).digest()
        token = base64.urlsafe_b64encode(
            f"{payload}:{base64.urlsafe_b64encode(signature).decode()}".encode()
        ).decode()
        return token


def verify_token(token: str, secret: str) -> Optional[str]:
    """
    Verify a JWT or HMAC token and return the user_id if valid, None otherwise.
    """
    if jwt:
        try:
            payload = jwt.decode(token, secret, algorithms=['HS256'])
            return payload.get('user_id')
        except (jwt.ExpiredSignatureError, jwt.InvalidTokenError):
            return None
    else:
        try:
            # Decode the base64 token
            decoded = base64.urlsafe_b64decode(token.encode()).decode()

            # Split into payload and signature
            parts = decoded.rsplit(':', 1)
            if len(parts) != 2:
                return None

            payload, signature_b64 = parts
            user_id, expiration = payload.split(':')
            expiration = int(expiration)

            # Check expiration
            if time.time() > expiration:
                return None

            # Verify signature
            expected_signature = base64.urlsafe_b64decode(signature_b64.encode())
            computed_signature = hmac.new(
                secret.encode('utf-8'),
                payload.encode('utf-8'),
                hashlib.sha256
            ).digest()

            if hmac.compare_digest(expected_signature, computed_signature):
                return user_id
            else:
                return None

        except (ValueError, KeyError, base64.binascii.Error):
            return None
```

This implementation provides:

1. **`hash_password`** - Uses bcrypt when available, falls back to PBKDF2-SHA256 with a random salt
2. **`verify_password`** - Verifies against both bcrypt and the fallback hash format
3. **`create_token`** - Creates JWT tokens with 15-minute expiration, with HMAC fallback
4. **`verify_token`** - Validates tokens and returns the user_id or None

The functions gracefully handle cases where `bcrypt` or `PyJWT` are not installed, providing secure fallback implementations using only the Python standard library.

